export const PRESENTATION_SCENES = PRESENTATION_DATA.scenes;
export const PRESENTATION_SCENE_MAP = new Map(PRESENTATION_SCENES.map(s=>[s.id,s]));
export const getPresentationScene = id => PRESENTATION_SCENE_MAP.get(id);
export const presentationFields = sceneOrId => { const s=typeof sceneOrId === "string" ? getPresentationScene(sceneOrId) : sceneOrId; return structuredClone(s?.defaultFields || {}); };
